/* Lesson s5c-computer-use: computer-use and browser agents.
   Story: Harbourline Imports, a small importer, must type the same shipment details into three supplier portals
   that have no API. It tries a browser agent on one of them: the agent sees only screenshots and answers with
   clicks at pixel positions and typed text, which a program then performs.
   Ideas: (1) a computer-use agent is the agent loop with a screenshot as the tool result and mouse and keyboard
   actions at pixel coordinates as the tool calls: it knows only what the last picture showed, and every action is
   a full model call; (2) so it breaks where pictures and pages disagree: the page moved between the screenshot and
   the click, and the model reported success over an empty form. Fixes live in the harness (wait for a still page,
   check the result in code), and the cheaper, steadier tools (an API, an upload, a scripted browser) come first.
   Depth: explain (screens 1-4), debug (screens 5-7, broken on purpose), when-not (screens 8 and 9).
   Data, all real:
   - docs/ai-path/runs/s5c-computer-use/portal.html: a made-up supplier portal built for this lesson; typing in
     "Cartons" shows a check notice that disappears 1200 ms after the last keystroke (the broken-on-purpose setup).
   - docs/ai-path/runs/s5c-computer-use/agent_run.mjs: the agent harness (headless Chrome, 520 x 680 window);
     run-a.out.txt (screenshot 200 ms after each action) and run-b.out.txt (screenshot once the page has been still
     for 1.5 s); screenshots in shots/; the embedded copies below come from embed_shots.sh.
   - recordings (main checkout) docs/ai-path/recordings/s5c-computer-use/a-1 … a-10 and b-1 … b-10: one model call
     per step, through scripts/ai/record.mjs.
   Lesson-local picture: a screenshot frame with a y scale and a click marker (.lx-s5c-computer-use-*), see
   ensureStyle() and shot(). Plain browser script. */
(() => {
  const ID = "s5c-computer-use";
  const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;
  const secs = ms => (ms / 1000).toFixed(1);

  /* ---------- Data copied from the runs and recordings ---------- */
  const VIEW = { w: 520, h: 680 };               // agent_run.mjs W, H (the window and the screenshot size)
  const NOTICE_MS = 1200;                        // portal.html: the notice hides 1200 ms after the last keystroke
  const SHOT_WAIT_A = 200;                       // agent_run.mjs run A: screenshot 200 ms after each action
  const STILL_MS_B = 1500;                       // agent_run.mjs run B: wait until nothing moved for 1.5 s
  // agent_run.mjs SYSTEM and TASK, as sent in every request
  const SYSTEM = "You fill in web forms by looking at screenshots of a browser. Each screenshot is 520 pixels wide and 680 pixels tall; x and y are pixels from its top-left corner. Each turn, call exactly one tool. type_text types into the field that has focus, so click a field before typing in it. When the form is submitted, or if you cannot go on, call finish with a short note.";
  const TASK = ["PO number: PO-4471", "Container number: KBSU 582130-6", "ETA: 2026-12-04", "Cartons: 120"];
  const TOOLS = [["click", "x, y", "Left-click at a point on the screenshot."], ["type_text", "text", "Type text into the focused field."], ["finish", "note", "Stop and report what happened."]];

  // From docs/ai-path/recordings/s5c-computer-use/a-1 … a-10.json (tool name and arguments not altered) and
  // docs/ai-path/runs/s5c-computer-use/run-a.out.txt (times in ms from the start; `hit` = the element under the
  // point at the moment of the click, from document.elementFromPoint; `tok` = prompt tokens of that call).
  // Rows: [step, screenshot at, action at, tool, arguments, hit, tok]
  const REC_A = {
    src: "s5c-computer-use/a-1 … a-10",
    provider: "openrouter", model: "google/gemini-2.5-flash", recordedAt: "2026-11-17",
    totalMs: 26739,
    steps: [[1,201,4962,"click","{\"x\":259,\"y\":206}","label: Container number",550],[2,5191,7904,"type_text","{\"text\":\"KBSU 582130-6\"}",null,563],[3,8139,10531,"click","{\"x\":259,\"y\":146}","label: PO number",583],[4,10737,13759,"type_text","{\"text\":\"PO-4471\"}",null,600],[5,13971,15809,"click","{\"y\":326,\"x\":259}","input: ETA",614],[6,16013,18324,"type_text","{\"text\":\"2026-12-04\"}",null,631],[7,18548,20153,"click","{\"x\":259,\"y\":386}","input: Cartons",649],[8,20357,22444,"type_text","{\"text\":\"120\"}",null,666],[9,22654,24946,"click","{\"x\":259,\"y\":506}","button: Clear form",677],[10,25149,26738,"finish","{\"note\":\"Shipment submitted successfully.\"}",null,694]],
    // run-a.out.txt step 9: boxes [left, top, right, bottom] in the screenshot (seen) and at the click
    seen9: { notice: [41,420,479,464], submit: [41,476,479,520], clear: [41,532,479,576] },
    atClick9: { submit: [41,420,479,464], clear: [41,476,479,520] },
    end: { events: ["clear"], submitted: null }
  };
  // From docs/ai-path/recordings/s5c-computer-use/b-1 … b-10.json and run-b.out.txt
  const REC_B = {
    src: "s5c-computer-use/b-1 … b-10",
    provider: "openrouter", model: "google/gemini-2.5-flash", recordedAt: "2026-11-17",
    totalMs: 35133,
    steps: [[1,1525,4250,"click","{\"y\":206,\"x\":259}","label: Container number",550],[2,5799,7559,"type_text","{\"text\":\"KBSU 582130-6\"}",null,563],[3,9165,10959,"click","{\"x\":259,\"y\":146}","label: PO number",583],[4,12475,14306,"type_text","{\"text\":\"PO-4471\"}",null,600],[5,15830,17476,"click","{\"x\":259,\"y\":326}","input: ETA",614],[6,18993,20552,"type_text","{\"text\":\"2026-12-04\"}",null,631],[7,22080,23749,"click","{\"x\":259,\"y\":386}","input: Cartons",649],[8,25267,26822,"type_text","{\"text\":\"120\"}",null,666],[9,29608,31989,"click","{\"y\":446,\"x\":259}","button: Submit shipment",677],[10,33520,35131,"finish","{\"note\":\"Shipment notice received. Reference SN-20931 for PO-4471.\"}",null,694]],
    seen9: { submit: [41,420,479,464], clear: [41,476,479,520] },
    end: { events: ["submit"], page: "Shipment notice received" }
  };
  // run-a.out.txt step 1 "seen": boxes of the four fields in the first screenshot
  const FIELDS1 = { po: [41,160,479,198], container: [41,230,479,268], eta: [41,300,479,338], cartons: [41,370,479,408], submit: [41,420,479,464], clear: [41,476,479,520] };
  const CAPTION = `Recorded model output, ${REC_A.recordedAt}`;

  // Small copies of shots/a-1, a-2, a-9, a-10, b-9, b-10 (embed_shots.sh: 390 px wide JPEG, same picture)
  const SHOTS = {"a-1":"data:image/jpeg;base64,","a-2":"data:image/jpeg;base64,","a-9":"data:image/jpeg;base64,","a-10":"data:image/jpeg;base64,","b-9":"data:image/jpeg;base64,","b-10":"data:image/jpeg;base64,",};

  /* ---------- Derived from the data ---------- */
  const A = REC_A.steps, B = REC_B.steps;
  const args = s => JSON.parse(s[4]);
  const callTxt = s => {
    const a = args(s);
    if (s[3] === "click") return `click(x=${a.x}, y=${a.y})`;
    if (s[3] === "type_text") return `type_text("${a.text}")`;
    return `finish("${a.note}")`;
  };
  const A9 = A[8], A10 = A[9], B9 = B[8], B10 = B[9];
  const P9 = args(A9), PB9 = args(B9);
  const GAP9 = A9[2] - A9[1];                                   // ms from screenshot 9 to the click
  const SHIFT = REC_A.seen9.submit[1] - REC_A.atClick9.submit[1]; // px the buttons moved up
  const inBox = (b, x, y) => x >= b[0] && x <= b[2] && y >= b[1] && y <= b[3];
  const CALLS_A = A.length, CALLS_B = B.length;
  const CLICKS_A = A.filter(s => s[3] === "click").length, TYPES_A = A.filter(s => s[3] === "type_text").length;
  const TOK = A.map(s => s[6]);
  const MEAN_GAP_A = Math.round(A.reduce((t, s) => t + (s[2] - s[1]), 0) / A.length);
  const EXTRA_B = REC_B.totalMs - REC_A.totalMs;
  // time from the previous action (or the start) to each screenshot, summed over the run
  const waits = steps => steps.reduce((t, st, i) => t + st[1] - (i ? steps[i - 1][2] : 0), 0);
  const WAIT_A = waits(REC_A.steps), WAIT_B = waits(REC_B.steps);
  // time from each screenshot to its action (the model's answer plus the recording script), summed over the run
  const thinks = steps => steps.reduce((t, st) => t + st[2] - st[1], 0);
  const THINK_A = thinks(REC_A.steps), THINK_B = thinks(REC_B.steps);

  /* ---------- Lesson-local style and helpers ---------- */
  function ensureStyle() {
    if (document.getElementById("lx-" + ID)) return;
    const s = document.createElement("style");
    s.id = "lx-" + ID;
    s.textContent = `
      .lx-${ID}-shots { display: flex; flex-wrap: wrap; gap: 14px 22px; margin: 16px 0 4px; }
      .lx-${ID}-fig { margin: 0; width: 100%; max-width: 362px; }
      .lx-${ID}-cap { font-size: 13.5px; color: var(--muted); margin: 0 0 6px; }
      .lx-${ID}-wrap { position: relative; padding-left: 32px; }
      .lx-${ID}-frame { position: relative; border: 1px solid var(--line); line-height: 0; }
      .lx-${ID}-frame img { width: 100%; height: auto; display: block; }
      .lx-${ID}-tick { position: absolute; left: 0; width: 28px; transform: translateY(-50%); font: 500 11px/1 var(--mono); color: var(--muted); text-align: right; }
      .lx-${ID}-tick::after { content: ""; position: absolute; right: -6px; top: 50%; width: 6px; border-top: 1px solid var(--faint); }
      .lx-${ID}-mark { position: absolute; width: 22px; height: 22px; margin: -11px 0 0 -11px; border-radius: 50%; border: 3px solid var(--ink); box-shadow: 0 0 0 3px var(--bg), inset 0 0 0 3px var(--bg); }
      .lx-${ID}-mark span { position: absolute; left: 26px; top: -4px; white-space: nowrap; font: 700 12px/1.2 var(--mono); color: var(--ink); background: var(--bg); padding: 2px 4px; border: 1px solid var(--line); }
      .lx-${ID}-mono { font: 500 14px/1.5 var(--mono); overflow-wrap: anywhere; }
      .lx-${ID}-opt { font: 500 14px/1.45 var(--mono); text-align: left; overflow-wrap: anywhere; }
      .lx-${ID}-list { margin: 12px 0 0; padding: 0; list-style: none; border-top: 1px solid var(--line); }
      .lx-${ID}-list li { padding: 7px 0; border-bottom: 1px solid var(--line); font-size: 15.5px; line-height: 1.45; }
      .lx-${ID}-list code { font: 600 14px var(--mono); }
      .lx-${ID}-steps { margin: 12px 0 0; padding: 0; list-style: none; border-top: 1px solid var(--line); counter-reset: none; }
      .lx-${ID}-steps li { display: grid; grid-template-columns: 3.2em 1fr; gap: 8px; padding: 6px 0; border-bottom: 1px solid var(--line); font: 500 14px/1.45 var(--mono); }
      .lx-${ID}-steps li b { color: var(--muted); font-weight: 600; }
      .lx-${ID}-steps li.lx-${ID}-now { border-left: 3px solid var(--ink); padding-left: 8px; }
      .lx-${ID}-req { margin: 12px 0 0; border: 1px solid var(--line); background: var(--sunk); padding: 10px 12px; }
      .lx-${ID}-req p { margin: 0 0 8px; font-size: 14.5px; line-height: 1.5; }
      .lx-${ID}-req pre { margin: 0 0 8px; white-space: pre-wrap; overflow-wrap: anywhere; font: 500 13.5px/1.5 var(--mono); }
    `;
    document.head.appendChild(s);
  }
  // A screenshot from the run with a y scale (screenshot pixels) and optional click marks [[x, y, label]].
  function shot(kit, key, title, marks) {
    const ticks = [100, 200, 300, 400, 500, 600].map(y => `<span class="lx-${ID}-tick" style="top:${(y / VIEW.h * 100).toFixed(2)}%">${y}</span>`).join("");
    const mk = (marks || []).map(([x, y, label]) => `<span class="lx-${ID}-mark" style="left:${(x / VIEW.w * 100).toFixed(2)}%;top:${(y / VIEW.h * 100).toFixed(2)}%">${label ? `<span>${kit.esc(label)}</span>` : ""}</span>`).join("");
    return `<figure class="lx-${ID}-fig"><figcaption class="lx-${ID}-cap">${kit.esc(title)}</figcaption>
      <div class="lx-${ID}-wrap">${ticks}<div class="lx-${ID}-frame"><img src="${SHOTS[key]}" width="390" height="510" alt="${kit.esc(title)}">${mk}</div></div></figure>`;
  }
  const shots = (...figs) => `<div class="lx-${ID}-shots">${figs.join("")}</div>`;
  const opt = (kit, s) => `<span class="lx-${ID}-opt">${kit.esc(s)}</span>`;
  const stepList = (kit, rows, now) => `<ol class="lx-${ID}-steps">${rows.map(s => `<li${s[0] === now ? ` class="lx-${ID}-now"` : ""}><b>${s[0]}</b><span>${kit.esc(callTxt(s))}</span></li>`).join("")}</ol>`;
  function ask(kit, opts, correct, picked, fb) {
    return `${kit.options(opts, { picked, correct })}${picked == null ? "" : kit.feedback(fb[picked][0], fb[picked][1])}`;
  }
  const taskList = kit => `<ul class="lx-${ID}-list">${TASK.map(t => `<li>${kit.esc(t)}</li>`).join("")}</ul>`;
  const toolList = kit => `<ul class="lx-${ID}-list">${TOOLS.map(([n, a, d]) => `<li><code>${kit.esc(n)}(${kit.esc(a)})</code> ${kit.esc(d)}</li>`).join("")}</ul>`;

  /* 1. The situation, and the first move: you are the agent, you only get the picture. */
  function firstMove({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const poY = Math.round((FIELDS1.po[1] + FIELDS1.po[3]) / 2), subY = Math.round((FIELDS1.submit[1] + FIELDS1.submit[3]) / 2);
    const C = [
      ["type_text(\"PO-4471\")", null],
      [`click(x=259, y=${poY})`, [259, poY]],
      [`click(x=259, y=${subY})`, [259, subY]],
      ["finish(\"Nothing to do yet\")", null]
    ];
    const RIGHT = 1;
    const a1 = A[0], p1 = args(a1);
    const fb = [
      ["No box in the picture has a cursor in it, so nothing has focus. <code>type_text</code> types into the focused field; here the letters would go nowhere. Something has to put the cursor in a box first.", false],
      [`Right. That point is inside the PO number box (y ${FIELDS1.po[1]} to ${FIELDS1.po[3]} on the scale). The recorded model did almost the same: its first call was <code>${kit.esc(callTxt(a1))}</code>. In the screenshot that point is on the words “Container number” above the second box, and clicking a field's label puts the cursor in that field. So it started with the container number. Any order works.`, true],
      [`That point is on “Submit shipment” (y ${FIELDS1.submit[1]} to ${FIELDS1.submit[3]}). The form is still empty, so the portal would only answer “Fill in every field.” The task needs four values typed first.`, false],
      ["The task is not done: the portal has no shipment from you yet. Finishing now reports work that never happened.", false]
    ];
    const paint = () => {
      const m = ans != null && C[ans][1] ? [[C[ans][1][0], C[ans][1][1], "your click"]] : [];
      if (ans === RIGHT) m.push([p1.x, p1.y, "model"]);
      el.innerHTML = `<h1>Three portals, no API</h1>
        <p class="lead">Harbourline Imports, a small importer, must enter the same shipment details into three supplier portals. None of them has an API (a way for a program to send the data directly). So a person types them in, three times, for every shipment.</p>
        <p class="lead">They try a <b>browser agent</b> on one portal: a model that works a web page the way a person does, by looking at it and clicking. This lesson is about that kind of agent: how it works, where it breaks, and when it is worth using. The agent gets this task:</p>
        ${taskList(kit)}
        <p class="lead">It cannot read the page's code. Its only view of the portal is a screenshot, ${VIEW.w} pixels wide and ${VIEW.h} tall. It can answer with one of three tools, and a program does the action in a real browser:</p>
        ${toolList(kit)}
        ${shot(kit, "a-1", "Screenshot 1, what the agent sees (y in pixels on the left; x = 259 is about the middle of each box)", m)}
        <p class="task">You are the agent. What is your first action?</p>
        <div class="lpanel">${ask(kit, C.map(c => opt(kit, c[0])), RIGHT, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === RIGHT) done(); });
    };
    paint();
  }

  /* 2. Predict the next action from the screenshot, twice: after step 1, and before the button. */
  function predict({ el, done, kit }) {
    ensureStyle();
    let turn = 0, ans = null;   // turn 0: step 2, turn 1: step 9, turn 2: finished
    const poMid = Math.round((FIELDS1.po[1] + FIELDS1.po[3]) / 2);
    const n = REC_A.seen9, subMid = Math.round((n.submit[1] + n.submit[3]) / 2), noticeMid = Math.round((n.notice[1] + n.notice[3]) / 2), clearMid = Math.round((n.clear[1] + n.clear[3]) / 2);
    const Q = [
      { key: "a-2", title: "Screenshot 2, after step 1", now: 1, right: 0,
        opts: ["type_text(\"KBSU 582130-6\")", "type_text(\"PO-4471\")", `click(x=259, y=${poMid})`, "finish(\"Container field selected\")"],
        fb: [null,
          ["Look at where the cursor is: the Container number box has the focus ring, not the PO box. The PO number would land in the container field.", false],
          [`y ${poMid} is inside the PO number box (y ${FIELDS1.po[1]} to ${FIELDS1.po[3]}). That moves the cursor out of the Container number box, which already has it, so a later step must click back there. Not a mistake on the form, but an extra action, and each action is one more full model call with a picture.`, false],
          ["Nothing has been typed yet. The task asks for four values and a submitted form.", false]] },
      { key: "a-9", title: "Screenshot 9, after step 8", now: 8, right: 0,
        opts: [`click(x=259, y=${subMid})`, `click(x=259, y=${noticeMid})`, `click(x=259, y=${clearMid})`, "finish(\"Shipment entered\")"],
        fb: [null,
          [`At y ${noticeMid} is the line “Checking carton count against the PO…”. It is a message from the portal, not a button. Clicking it does nothing.`, false],
          [`At y ${clearMid} is “Clear form”. That would empty all four boxes you just filled.`, false],
          ["All four values are in, but nothing has been sent. The portal only has the shipment after “Submit shipment”.", false]] }
    ];
    const paint = () => {
      const q = Q[Math.min(turn, 1)];
      const marks = turn === 2 ? [[P9.x, P9.y, "model"]] : (ans != null && /click/.test(q.opts[ans]) ? [[259, +q.opts[ans].match(/y=(\d+)/)[1], "your click"]] : []);
      const fin = turn === 2;
      el.innerHTML = `<h1>Predict the next action</h1>
        <p class="lead">Every step, the program takes a new screenshot and sends it with the task and the list of actions so far. The model answers with one action. The program does it, and the loop starts again.</p>
        ${stepList(kit, A.slice(0, q.now), q.now)}
        ${shot(kit, q.key, q.title, marks)}
        ${fin ? "" : `<p class="task">${turn === 0 ? "This is the screenshot after step 1. What should step 2 be?" : `Steps 2 to 8 clicked into each box and typed the four values. What should step ${A9[0]} be?`}</p>`}
        <div class="lpanel">${fin
          ? kit.feedback(`Right, and the recorded model made the same moves: step 2 was <code>${kit.esc(callTxt(A[1]))}</code>, and step ${A9[0]} was <code>${kit.esc(callTxt(A9))}</code>, marked “model” above. In this screenshot that point is inside “Submit shipment” (y ${n.submit[1]} to ${n.submit[3]}). Hold on to that: the next screens show what the click really hit.`, true)
          : ask(kit, q.opts.map(o => opt(kit, o)), q.right, ans, q.fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => {
        ans = +b.dataset.i;
        if (ans === Q[turn].right) { turn++; ans = null; paint(); if (turn === 2) done(); return; }
        paint();
      });
    };
    paint();
  }

  /* 3. Spot the idea: the model only has the picture, and answers in pixels. */
  function spotIdea({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const a1Submit = FIELDS1.submit, a9Submit = REC_A.seen9.submit;
    const opts = [
      "It read the page's HTML and found the button by its id",
      "It found the words “Submit shipment” in the picture and gave their position in screenshot pixels",
      "It remembered where the button was from the first screenshot",
      "The portal told it, through the portal's API"
    ];
    const fb = [
      ["Look at the request: two blocks of text and one picture. No HTML was sent, and the model never saw the page's code.", false],
      [`Right. That is a <b>computer-use agent</b>: screenshots in, mouse and keyboard actions out, at pixel positions. It is the agent loop you know: the screenshot plays the part of the tool result. (Our small program sends each screenshot in a new message with the list of actions; ready-made tools send it back as the tool result.) The model never touches the browser. Your program does the click and takes the next picture. Vendors ship ready-made versions of this tool. Anthropic's, for example, has actions such as <code>screenshot</code>, <code>left_click</code>, <code>type</code>, <code>key</code> and <code>scroll</code>, and your application performs each one and returns screenshots. A <b>browser agent</b> is the same idea limited to a web browser.`, true],
      [`It has no memory between calls, and the request carries only the action list and the newest picture. Also, the button moved: in screenshot 1 “Submit shipment” was at y ${a1Submit[1]} to ${a1Submit[3]}, in screenshot 9 at y ${a9Submit[1]} to ${a9Submit[3]}. The model read the current picture.`, false],
      ["The portal has no API. That is the whole reason Harbourline is trying an agent.", false]
    ];
    const paint = () => {
      el.innerHTML = `<h1>What does the agent know?</h1>
        <p class="lead">This is everything the program sent for step ${A9[0]}, apart from the three tool definitions:</p>
        <div class="lx-${ID}-req">
          <p><b>Instructions</b></p><pre>${kit.esc(SYSTEM)}</pre>
          <p><b>Message</b></p><pre>Task: enter this shipment in the supplier portal and submit it.\n${kit.esc(TASK.join("\n"))}\n\nActions so far:\n${A.slice(0, 8).map((s, i) => `${i + 1}. ${kit.esc(callTxt(s))}`).join("\n")}\n\nThe current screenshot:</pre>
          <p><b>One picture:</b> screenshot ${A9[0]}, the one on the last screen.</p>
        </div>
        <p class="lead">The model answered with one tool call (in the model API's format, trimmed):</p>
        <pre class="lx-${ID}-mono">tool_calls[0].function = {
  name: "${kit.esc(A9[3])}",
  arguments: "${kit.esc(A9[4].replace(/"/g, '\\"'))}"
}</pre>
        <p class="lx-${ID}-cap">${CAPTION}. The step lists in this lesson write the same call as <code>${kit.esc(callTxt(A9))}</code>, the form the program sends back in “Actions so far”. Other APIs use a different shape for the same thing.</p>
        <p class="task">How did it know where “Submit shipment” was?</p>
        <div class="lpanel">${ask(kit, opts, 1, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === 1) done(); });
    };
    paint();
  }

  /* 4. What one form costs: count the model calls. */
  function countCalls({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const choices = [1, 5, CALLS_A, 2 * CALLS_A];
    const fbFor = v => v === CALLS_A
      ? [`Right: ${CALLS_A}. Each field took two calls, one <code>click</code> and one <code>type_text</code> (${CLICKS_A - 1} clicks and ${TYPES_A} <code>type_text</code> calls), then one click on the button and one <code>finish</code>. Every call carried a fresh screenshot. The whole run took ${secs(REC_A.totalMs)} seconds, about ${secs(MEAN_GAP_A)} seconds per step between a screenshot and the action (the model's answer, plus our recording script). The prompt grew from ${TOK[0]} to ${TOK[TOK.length - 1]} tokens per call: the picture stayed the same size, and the list of actions got longer. If the portal had an API, this would be one request with four fields, no screenshot and no model at all. Harbourline has three portals and pays this for each shipment on each one.`, true]
      : v === 1
        ? ["One call would mean the model returns the whole form at once. But it can only act on what it sees, and each action changes the screen. So it acts once, looks again, and acts again.", false]
        : v === 5
          ? ["Five is one call per field plus one. But a field needs two actions: a click to put the cursor in it, then the typing. And the model also has to press the button and then say it is done.", false]
          : [`That would be two calls per action. Here the model answers each screenshot with exactly one action, so it is one call per action: ${CALLS_A}.`, false];
    const paint = () => {
      el.innerHTML = `<h1>What one form costs</h1>
        <p class="lead">One action per model call, and each call needs a new screenshot. The form has four fields and one button. The run ends when the model calls <code>finish</code>.</p>
        <p class="task">How many model calls did the recorded run make, from the first click to <code>finish</code>?</p>
        <div class="lpanel">${kit.options(choices.map(String), { picked: ans == null ? null : choices.indexOf(ans), correct: choices.indexOf(CALLS_A), num: true })}
        ${ans == null ? "" : kit.feedback(...fbFor(ans))}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = choices[+b.dataset.i]; paint(); if (ans === CALLS_A) done(); });
    };
    paint();
  }

  /* 5. Broken on purpose: which step emptied the form, and why did the click land there? */
  function brokenClick({ el, done, kit }) {
    ensureStyle();
    let part = 0, ans = null;   // part 0: which step, part 1: why, part 2: finished
    const s = REC_A.seen9, c = REC_A.atClick9;
    const P = [
      { right: 1, opts: [`Step ${A[7][0]}: ${callTxt(A[7])}`, `Step ${A9[0]}: ${callTxt(A9)}`, `Step ${A10[0]}: ${callTxt(A10)}`],
        fb: [["Screenshot 9 shows 120 in the Cartons box, so the typing worked. The form was still full after step 8.", false], null,
          ["<code>finish</code> does not touch the page; it only ends the run. The form was already empty in the screenshot the model saw before step 10.", false]] },
      { right: 1, opts: ["The model misread the picture and aimed at “Clear form”", "The page moved between the screenshot and the click", "The program scaled the screenshot and forgot to scale the click back", "The portal's buttons are wired the wrong way round"],
        fb: [[`In screenshot ${A9[0]}, the point (${P9.x}, ${P9.y}) is inside “Submit shipment” (y ${s.submit[1]} to ${s.submit[3]}). “Clear form” was lower, at y ${s.clear[1]} to ${s.clear[3]}. The model aimed right for the picture it was given.`, false], null,
          [`A real and common bug: if the program shrinks screenshots before sending them, it must scale the model's coordinates back up before clicking. Not here: the screenshot was ${VIEW.w} by ${VIEW.h}, the same size as the browser window, and the eight actions before it landed where they should.`, false],
          ["The run in which the agent pressed the right spot (next screen) submitted the shipment. The buttons do what their labels say.", false]] }
    ];
    const paint = () => {
      const q = P[Math.min(part, 1)];
      const fin = part === 2;
      el.innerHTML = `<h1>Broken on purpose: the form came back empty</h1>
        <p class="lead">This is the end of the same run. The shipment was never sent: the form ended up empty. The model's last call was:</p>
        <p class="lx-${ID}-mono">${kit.esc(callTxt(A10))}</p>
        <p class="lx-${ID}-cap">${CAPTION}</p>
        ${shots(shot(kit, "a-9", `Screenshot ${A9[0]}, before the click`, [[P9.x, P9.y, "click"]]), shot(kit, "a-10", `Screenshot ${A10[0]}, after it`))}
        ${part >= 1 ? `<p class="lead">From the run's log: at the moment of the click, the element under (${P9.x}, ${P9.y}) was <b>${kit.esc(A9[5].replace("button: ", ""))}</b>. The screenshot was taken at ${secs(A9[1])} s, the click came at ${secs(A9[2])} s.</p>` : ""}
        ${fin ? "" : `<p class="task">${part === 0 ? "Which step emptied the form?" : `In screenshot ${A9[0]} the point was inside “Submit shipment”. Why did the click hit “Clear form”?`}</p>`}
        <div class="lpanel">${fin
          ? kit.feedback(`Right. The check notice (“Checking carton count against the PO…”) disappears ${NOTICE_MS} ms after the last keystroke. The program took the screenshot ${SHOT_WAIT_A} ms after typing, so the notice was in it. Then ${secs(GAP9)} s passed before the click, while the model answered (that time also includes our recording script). By then the notice was gone and everything under it had moved up ${SHIFT} pixels: “Submit shipment” to y ${c.submit[1]} to ${c.submit[3]}, and “Clear form” into the place where Submit had been (y ${c.clear[1]} to ${c.clear[3]}). The model acts on an old picture of a live page. A person sees the button jump; the agent does not, because it is not looking between screenshots. (We built this portal for the lesson and made the notice disappear on a timer, so the failure would happen for real.)`, true)
          : ask(kit, q.opts.map(o => opt(kit, o)), q.right, ans, q.fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => {
        ans = +b.dataset.i;
        if (ans === P[part].right) { part++; ans = null; paint(); if (part === 2) done(); return; }
        paint();
      });
    };
    paint();
  }

  /* 6. The fix in the harness, and what it costs: run B. */
  function fixHarness({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const RIGHT = 1;
    const opts = [
      "Use a stronger model that reads buttons better",
      "Before each screenshot, wait until nothing on the page has moved for a moment",
      "Take the screenshot sooner after each action",
      "Add “be careful with buttons” to the instructions"
    ];
    const sb = REC_B.seen9.submit;
    const fb = [
      ["The model already aimed at the right button in the picture it got. The problem was the picture: it showed a page that changed before the click.", false],
      [`Right. We ran the same task again with that one change: the program waits until no box has moved for ${secs(STILL_MS_B)} s before each screenshot. Screenshot ${B9[0]} now shows the page after the notice was gone, with “Submit shipment” at y ${sb[1]} to ${sb[3]}. The model called <code>${kit.esc(callTxt(B9))}</code>, which hit <b>${kit.esc(B9[5].replace("button: ", ""))}</b>, and its last call was <code>${kit.esc(callTxt(B10))}</code>. The cost: the run took ${secs(REC_B.totalMs)} s instead of ${secs(REC_A.totalMs)} s, ${secs(EXTRA_B)} s more for one form. The waits before screenshots added up to ${secs(WAIT_B)} s, against ${secs(WAIT_A)} s in the broken run. The model happened to answer faster in this run (${secs(THINK_B)} s in all, against ${secs(THINK_A)} s), so the total grew by less than the waits did. Waiting narrows the gap but does not close it: a page can still change while the model is answering. A <b>browser script</b> (code that drives a browser through fixed steps, with no model) solves this by waiting, before each click, until the element is visible and has stopped moving. An agent working from pictures only has its screenshots.`, true],
      [`That is what the broken run did: the screenshot came ${SHOT_WAIT_A} ms after typing, which is why it caught the notice before it went away. Sooner makes the picture more out of date, not less.`, false],
      ["The model cannot be careful about a change it never saw. In its picture, its click was right. Instructions do not fix a picture that is out of date.", false]
    ];
    const paint = () => {
      el.innerHTML = `<h1>Fix the harness, not the model</h1>
        <p class="lead">The <b>harness</b> is your program around the model: it takes the screenshots, does the clicks and runs the loop. The broken run's harness took each screenshot ${SHOT_WAIT_A} ms after the last action.</p>
        ${ans === RIGHT ? shots(shot(kit, "b-9", `Fixed run, screenshot ${B9[0]}`, [[PB9.x, PB9.y, "click"]]), shot(kit, "b-10", `Fixed run, screenshot ${B10[0]}`)) + `<p class="lx-${ID}-cap">${CAPTION}</p>` : ""}
        <p class="task">Which change to the harness stops step ${A9[0]} from going wrong?</p>
        <div class="lpanel">${ask(kit, opts, RIGHT, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === RIGHT) done(); });
    };
    paint();
  }

  /* 7. The second fault in the broken run: who decides that the job is done? */
  function whoDecides({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const RIGHT = 2;
    const opts = [
      "The model's finish note: it saw the last screenshot",
      `The number of steps: ${CALLS_A} steps means the form was filled and sent`,
      "A check in your own code: the page must show “Shipment notice received” and a reference number, or the run counts as failed and goes to a person",
      "Ask the model again: “Are you sure it was submitted?”"
    ];
    const fb = [
      [`It did see it, and still wrote <code>${kit.esc(args(A10).note)}</code> over an empty form. Anthropic's computer-use documentation warns about exactly this: a model sometimes acts as if its actions succeeded without checking their results.`, false],
      [`Both runs took ${CALLS_A} steps. One submitted the shipment, the other cleared the form. The step count says nothing about the result.`, false],
      [`Right. In the fixed run, the last screenshot says “${kit.esc(REC_B.end.page)}” with a reference, and the program can read that for itself (or wait for the supplier's confirmation). In the broken run there is no reference, so the code marks it failed, whatever the note says. The model's note is a claim; the confirmation on the page is the evidence. For a step that cannot be undone, such as a submit or a payment, also have a person approve it before the click.`, true],
      ["You would be asking the same model that already reported success over an empty form to grade itself. It may agree with itself. The check belongs in code that reads the page.", false]
    ];
    const paint = () => {
      el.innerHTML = `<h1>Who decides it worked?</h1>
        <p class="lead">Look again at the broken run. Before step ${A10[0]} the model received this screenshot, and called <code>${kit.esc(callTxt(A10))}</code>.</p>
        ${shots(shot(kit, "a-10", `Broken run, screenshot ${A10[0]}`))}
        <p class="lx-${ID}-cap">${CAPTION}</p>
        <p class="task">Harbourline needs to know, for each shipment, whether the portal really has it. What should decide that?</p>
        <div class="lpanel">${ask(kit, opts, RIGHT, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === RIGHT) done(); });
    };
    paint();
  }

  /* 8. The big picture: what for, when, when not, what it costs. */
  function bigPicture({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const RIGHT = 1;
    const opts = [
      "Portal A: it has a page where you can upload a spreadsheet of shipments",
      "Portal B: no API, no upload, about five shipments a week, and its layout changes a few times a year",
      "Portal C: no API, but its form never changes and Harbourline enters about 400 shipments a day there"
    ];
    const fb = [
      ["An upload is a way in that was built for data. One file, no screenshots, no model calls, and the portal itself checks it. Use the upload.", false],
      ["Right. No other way in, and low volume. A layout that changes a few times a year may break a fixed script each time, while the agent reads whatever the new screen shows. A few slow, watched runs a week are a fair price. Keep a person approving the submit and a code check on the confirmation.", true],
      ["At that volume, a model call per click is slow and adds up, and every run can go wrong in a new way. A form that never changes is what a browser script is for: written once, it finds each field by its label, waits for it, and does the same thing every time, with no model.", false]
    ];
    const paint = () => {
      el.innerHTML = `<h1>When to use an agent that clicks</h1>
        <p class="lead"><b>For:</b> software that only has screens: no API, no export, no upload. Old desktop programs and portals like Harbourline's.</p>
        <p class="lead"><b>Not</b> when there is an API or an upload: use that. Not for high volume on a page that stays the same: a browser script is faster and repeatable. A middle way: browser tools that give the model the page's structure (its buttons, fields and labels) instead of pixels.</p>
        <p class="lead"><b>Costs:</b> a model call with a picture for every action, so seconds per step. The agent goes wrong when the page moves between a screenshot and a click. It acts with your logged-in account, and text on a page can try to give it orders. So run it in a separate browser or machine without saved passwords, and have a person approve anything that cannot be undone.</p>
        <p class="task">Harbourline's three portals are not the same. On which one is the agent the right tool?</p>
        <div class="lpanel">${ask(kit, opts, RIGHT, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === RIGHT) done(); });
    };
    paint();
  }

  /* 9. Recognise it in new situations, including two where it is the wrong tool. */
  const CASES = [
    ["A locksmith firm's old desktop job-booking program has no API and no export. Each week, staff copy about twenty job requests from emails into it by hand.", true,
      "Yes. Screens are the only way in, and the volume is small. Let it work in a separate machine, and have staff check each job before it is saved.",
      "The program has only screens: no API, no export, nothing a script can call. At twenty a week, a slow agent that a person checks is a fair trade."],
    ["After every release, check that your own web shop's checkout still works: add an item, pay with a test card, see the receipt.", false,
      "No. This is a test, and a test must do the same thing every run and stop with a clear error when something breaks. A browser script finds each button by its label and stops when one is missing. An agent might work around a broken button and report success, which hides the bug the test is for.",
      "You own this page and its steps never change. A scripted browser test is repeatable and fails when something breaks; an agent that looks at pictures can find another way round a broken button and pass anyway."],
    ["Post the day's sales total to a team chat tool that has a documented API for sending messages.", false,
      "No. The tool has an API, so this is one request from a small script. Driving the chat app through screenshots would be many slow, paid model calls to do the same thing, with more ways to fail.",
      "There is an API for exactly this. One request does it. Screenshots and clicks would add model calls and failure points for nothing."],
    ["A customs broker looks up the status of about ten declarations a day on a government website with no API. The site's layout changes now and then, and the job only reads, it never submits.", true,
      "Yes. No API, low volume, a layout a fixed script would trip over, and nothing is changed on the site, so a mistake costs little. Still compare the status it reports with the page's own text in code.",
      "There is no other way in, and the job only reads, so a wrong click cannot do lasting harm. Ten a day is a pace where a few seconds per step do not matter, and a changing layout is where pictures beat a fixed script."]
  ];
  function recognise({ el, done, kit }) {
    ensureStyle();
    const ans = CASES.map(() => null);
    const paint = () => {
      el.innerHTML = `<h1>Agent that clicks, or not?</h1>
        <p class="lead">Four jobs from other places. A computer-use agent means: screenshot in, a click or keystrokes out, a model call per action.</p>
        <p class="task">Would you use one for each job? Pick again if you change your mind.</p>
        ${CASES.map(([q, y, yes, no], i) => `<div class="lcase" id="c${i}"><p>${q}</p>${kit.options(["Yes", "No"], { picked: ans[i], correct: y ? 0 : 1 })}${ans[i] == null ? "" : kit.feedback(ans[i] === (y ? 0 : 1) ? yes : no, ans[i] === (y ? 0 : 1))}</div>`).join("")}`;
      el.querySelectorAll(".lcase").forEach((c, i) => c.querySelectorAll("button").forEach(b => b.onclick = () => {
        ans[i] = +b.dataset.i; paint();
        if (CASES.every(([, y], j) => ans[j] === (y ? 0 : 1))) done();
      }));
    };
    paint();
  }

  /* 10. What next. */
  function whatNext({ el, done, kit, topic }) {
    const nx = topic && topic.next;
    el.innerHTML = `<h1>You can judge a clicking agent</h1>
      <p class="lead">You played the agent from screenshots, saw that every action is a model call that answers with pixel positions, found the step where the page moved after the screenshot was taken, and saw why the harness, not the model, must wait for a still page and check the result.</p>
      <p class="lead"><b>Practice:</b> this lesson was the practice. Next time someone proposes an agent that clicks, ask first whether there is an API or an upload.</p>
      ${nx ? `<p class="lead"><b>Next:</b> ${kit.esc(nx.title)}. Here the model drove someone else's screen; next, its output becomes part of your own interface.</p>` : ""}`;
    done();
  }

  LessonKit.define(ID, {
    title: "Computer-use and browser agents",
    checked: "2026-11-18",
    sources: [
      "https://platform.claude.com/docs/en/agents-and-tools/tool-use/computer-use-tool",
      "https://github.com/microsoft/playwright-mcp",
      "https://playwright.dev/docs/actionability",
      "https://playwright.dev/docs/locators",
      "https://openrouter.ai/docs/guides/features/tool-calling"
    ],
    interview: [
      {
        q: "Your team wants an agent to enter orders into a partner's web portal that has no API. What do you check and build before you let it run without someone watching?",
        good: [
          "Ask the partner for an API, a file upload or an export first; use the screen only when there is no other way in",
          "Run it in a separate browser or machine, without saved passwords, with only the sites it needs",
          "Make the harness wait for a still page before each screenshot, and check the result of each step",
          "Decide success in code from the page (a confirmation and reference number), not from the model's own report",
          "Put a person's approval before submits and payments, cap the steps, and keep the screenshots of every run"
        ],
        weak: "Pick the strongest vision model and let it run. That ignores that the model only sees old pictures, can report success that did not happen, and acts with the company's account."
      },
      {
        q: "A browser agent worked in testing, but in production it sometimes clicks the wrong button. How do you find out why?",
        good: [
          "Replay the run: put each screenshot next to the click coordinates the model returned",
          "Check whether the point was right in the picture the model got; if yes, the page changed before the click (a banner, a spinner, late loading)",
          "Check that screenshots are not scaled without scaling the coordinates back",
          "Fix it in the harness: wait for the page to be still, take a fresh screenshot, verify after each action"
        ],
        weak: "Tell the model in the prompt to be more careful. The model aimed correctly at the picture it was given, so a prompt cannot fix it."
      }
    ],
    screens: [firstMove, predict, spotIdea, countCalls, brokenClick, fixHarness, whoDecides, bigPicture, recognise, whatNext],
    walk: [
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]", "[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]", "[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["#c1 [data-wrong]"], right: CASES.map((_, i) => `#c${i} [data-right]`) },
      { right: [] }
    ]
  });
})();
